package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.util.Log;import android.graphics.Bitmap;import java.io.*;
public class Smoke extends Instrumentation {
 private String target="app.layan.quran.ui.QuranActivity";
 public void onCreate(Bundle args){super.onCreate(args);if(args!=null&&args.getString("target")!=null)target=args.getString("target");if(args!=null&&"true".equals(args.getString("seedCairo")))getTargetContext().getSharedPreferences("layan_local",0).edit().putLong("prayer_lat",Double.doubleToLongBits(30.0444)).putLong("prayer_lon",Double.doubleToLongBits(31.2357)).putLong("prayer_location_time",System.currentTimeMillis()).putFloat("prayer_accuracy",100).commit();start();}
 public void onStart(){Bundle out=new Bundle();try{Intent i=new Intent().setClassName("app.layan.quran",target).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity a=startActivitySync(i);waitForIdleSync();SystemClock.sleep(5000);waitForIdleSync();if(target.endsWith("QuranActivity")&&a.findViewById(0x7f090268)==null)throw new AssertionError("Surah row title is absent after layout");Bitmap shot=getUiAutomation().takeScreenshot();File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,target.substring(target.lastIndexOf('.')+1)+".png"))){if(shot!=null)shot.compress(Bitmap.CompressFormat.PNG,100,f);}out.putString("activity",a.getClass().getName());out.putString("result","opened and stayed running for five seconds");finish(Activity.RESULT_OK,out);}catch(Throwable e){Log.e("LayanSmoke","Screen launch failed",e);out.putString("error",Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
 public boolean onException(Object obj,Throwable e){Log.e("LayanSmoke","Application exception",e);return super.onException(obj,e);}
}
